INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13001, 'Psalms 6:4', 'Psalms', 6, 4, '&nbsp;اے مالِکه خُدايه ما خلاص کړه ما ته راوګرځه، ما بچ کړه د خپلې لوئې مينې سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13002, 'Psalms 6:5', 'Psalms', 6, 5, '&nbsp;څوک نۀ يادوى تا چې کله مړۀ شى. څوک دے چې ستا ثناء صِفت يې په قبر کښې کړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13003, 'Psalms 6:6', 'Psalms', 6, 6, '&nbsp;ستړے يم ډېر په ژړېدو سره، بستره زما لمده شى ټوله شپه په ژړېدو سره، او بالښت مې لوند شى په اوښکو سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13004, 'Psalms 6:7', 'Psalms', 6, 7, '&nbsp;سترګې مې کمزورې شوې خفګان سره، سترګو مې کار پرېښے دے دشمنۍ سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13005, 'Psalms 6:8', 'Psalms', 6, 8, '&nbsp;ځئ زما نه ځئ ټول بدعمله رانه لاړ شئ، زما ژړا مالِک خُدائ اورېدلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13006, 'Psalms 6:9', 'Psalms', 6, 9, '&nbsp;د رحم دپاره سوال مې اورېدلے دے، مالِک خُدائ، دُعا زما يې قبوله کړې ده مالِک خُدائ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13007, 'Psalms 6:10', 'Psalms', 6, 10, '&nbsp;يريږى به، شرميږى به، زما ټول دشمنان، راواپس به کړى هغوئ په ناګهانه بې‌عزتۍ سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13008, 'Psalms 7:1', 'Psalms', 7, 1, '&nbsp;اے مالِکه خُدايه، پاکه خُدايه، تۀ زما پناه يې، د هغه خلقو نه ما خلاص کړه او ما بچ کړه څوک چې راپسې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13009, 'Psalms 7:2', 'Psalms', 7, 2, '&nbsp;ګنې ما به د ازمرى په شانې وشلوى ټوټې به مې کړى، هيڅ څوک به مې نۀ وى چې د هغوئ نه ما بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13010, 'Psalms 7:3', 'Psalms', 7, 3, '&nbsp;اے مالِکه خُدايه، زما پاکه خُدايه، کۀ ما د اِنصاف نه کار اخستے نۀ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13011, 'Psalms 7:4', 'Psalms', 7, 4, '&nbsp;کۀ ما د خپل دوست سره بد کړې وى کۀ ناحقه مې دشمن باندې حمله کړې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13012, 'Psalms 7:5', 'Psalms', 7, 5, '&nbsp;نو بيا دې دشمن راپسې شى ما دې ووهى. ما دې پرېږدى بې‌عزتۍ سره په خاورو کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13013, 'Psalms 7:6', 'Psalms', 7, 6, '&nbsp;اے مالِکه خُدايه د غصې سره راپاڅه، زما د دشمن د غصې په مقابل کښې راپورته شه، راپورته شه، زما پاکه خُدايه، په دوئ باندې خپل عدل او اِنصاف راوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13014, 'Psalms 7:7', 'Psalms', 7, 7, '&nbsp;راغونډ کړه ټول قومونه خپل ځان ته، د خپل عرش نه په هغوئ بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13015, 'Psalms 7:8', 'Psalms', 7, 8, '&nbsp;مالِک خُدائ په خپله د قومونو عدالت کوى. تۀ زما د صداقت اعلان وکړه، زۀ بې‌ګناه يم، اے لويه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13016, 'Psalms 7:9', 'Psalms', 7, 9, '&nbsp;ختم کړه ظلمونه د ظالم ختم کړه، آباد کړه صادقان صادقه خُدايه، د زړۀ منصوبې او فکرونه تۀ معلوموې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13017, 'Psalms 7:10', 'Psalms', 7, 10, '&nbsp;هغه خُدائ تعالىٰ خو زما ډال دے، بچ کوونکے چې د زړونو صادقانو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13018, 'Psalms 7:11', 'Psalms', 7, 11, '&nbsp;خُدائ پاک صادق اِنصاف دار دے، بدکارو ته هره ورځ په قهر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13019, 'Psalms 7:12', 'Psalms', 7, 12, '&nbsp;کۀ څوک چرې په خپله توبه نۀ کړى، خُدائ به خپله تُوره ورته تېره کړى، نو ليندې ته به لاس پورته کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13020, 'Psalms 7:13', 'Psalms', 7, 13, '&nbsp;کړى هغه به تياره وسله تباه کوونکى، او وُلى به خپل غشى بلېدونکى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13021, 'Psalms 7:14', 'Psalms', 7, 14, '&nbsp;څنګه د بدو منصوبې جوړوى، بدعمله خلق ګوره د مصيبت نه هغوئ ډک وى او فريب کاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13022, 'Psalms 7:15', 'Psalms', 7, 15, '&nbsp;هغوئ د بل د غورزېدو دپاره ډوبه کنده تياروى په هم دې کنده کښې به په خپله ورغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13023, 'Psalms 7:16', 'Psalms', 7, 16, '&nbsp;کوم مصيبت چې جوړوى هغوئ به خپله په کښې ګېر شى، هغه ظلمونه د هغوئ په خپل سر انبار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13024, 'Psalms 7:17', 'Psalms', 7, 17, '&nbsp;شُکر به کوم د مالِک خُدائ چې هغه اِنصاف کوونکے دے وايم به زۀ د مالِک خُدائ تعالىٰ ثناء صِفت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13025, 'Psalms 8:1', 'Psalms', 8, 1, '&nbsp;اے مالِکه خُدايه، زمونږ ربه، ټوله دُنيا کښې ستا نوم عظيم ‎‎دے، پاس په آسمانونو کښې ‎دې خپل جلال جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13026, 'Psalms 8:2', 'Psalms', 8, 2, '&nbsp;تا تى رودونکو او لويو ماشومانو ته خپل ثناء صِفت ښودلے دے خپل مخالفين او دشمنان دې په دې چپ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13027, 'Psalms 8:3', 'Psalms', 8, 3, '&nbsp;زۀ کله چې ستا د ګوتو کار ته ګورم، ستا په آسمانونو باندې غور کوم، په خپل ځائ چې مقرر دى ستورو سپوږمۍ ته ګورم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13028, 'Psalms 8:4', 'Psalms', 8, 4, '&nbsp;انسان څۀ وى چې تۀ پرې نظر ساتې، نو بنيادم څۀ وى چې تۀ يې خيال ساتې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13029, 'Psalms 8:5', 'Psalms', 8, 5, '&nbsp;تا د فرښتو نه لږ کم کړے دے تا هم د جلال او عزت تاج ورپه سر کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13030, 'Psalms 8:6', 'Psalms', 8, 6, '&nbsp;تا په خپل مخلوق بنيادم واکمن کړے دے، تا په هر څيز پوره اختيار ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13031, 'Psalms 8:7', 'Psalms', 8, 7, '&nbsp;کۀ ګډې کۀ رَمې د بيابان، او کۀ دى ټول ځنګلى ځناوران.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13032, 'Psalms 8:8', 'Psalms', 8, 8, '&nbsp;کۀ مارغان دى په هوا کښې او کۀ کبان دى سمندر کښې، يا نور داسې څيزونه چې ګرځيږى سمندر کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13033, 'Psalms 8:9', 'Psalms', 8, 9, '&nbsp;اے مالِکه خُدايه، زمونږ ربه، ټوله دُنيا کښې ستا نوم عظيم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13034, 'Psalms 9:1', 'Psalms', 9, 1, '&nbsp;زۀ به د خپل ټول زړۀ نه د مالِک خُدائ ثناء صِفت کوم، زۀ به ستا ټول عجيبه کارونه بيان کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13035, 'Psalms 9:2', 'Psalms', 9, 2, '&nbsp;زۀ به يم خوشحاله او ستا له سببه خوشحالى کوم، اے خُدائ تعالىٰ زۀ به په سندرو کښې ستا د نوم ثناء صِفت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13036, 'Psalms 9:3', 'Psalms', 9, 3, '&nbsp;زما دشمنان چې کله وتښتېدل، هغوئ تيندکونه وخوړل او ستا په وړاندې تباه شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13037, 'Psalms 9:4', 'Psalms', 9, 4, '&nbsp;تا زما په حق کښې وکړه فېصله، ناست يې په خپل تخت په اِنصاف خپل عدالت کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13038, 'Psalms 9:5', 'Psalms', 9, 5, '&nbsp;بدعمله تباه کړى دى تا، قومونه رټلى دى تا، د تل دپاره دې نام و نشان ورله ختم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13039, 'Psalms 9:6', 'Psalms', 9, 6, '&nbsp;بې‌کچه تباهى دې د دشمن ښارونه نابود کړى دى، نام و نشان د هغوئ دې ختم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13040, 'Psalms 9:7', 'Psalms', 9, 7, '&nbsp;خو د تل دپاره مالِک خُدائ به بادشاهى کوى، قائم کړے يې خپل تخت دے او اِنصاف به کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13041, 'Psalms 9:8', 'Psalms', 9, 8, '&nbsp;او هغه اِنصاف سره په دُنيا عدالت کوى، هغه به په قومونو په اِنصاف سره حکومت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13042, 'Psalms 9:9', 'Psalms', 9, 9, '&nbsp;د مظلومانو دپاره مالِک خُدائ د امان ځائ دے، په وخت د مصيبت هغه مضبوط د پناه ځائ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13043, 'Psalms 9:10', 'Psalms', 9, 10, '&nbsp;څوک چې دې نوم پېژنى په تا توکل کوى، مالِکه خُدايه، څوک چې دې لټون کوى تا يواځې نۀ دى پرېښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13044, 'Psalms 9:11', 'Psalms', 9, 11, '&nbsp;په سندرو کښې د هغه مالِک خُدائ ثناء صِفت کوى، څوک چې په صيون کښې په تخت ناست دے، قومونو ته بيان کړئ هغۀ چې څۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13045, 'Psalms 9:12', 'Psalms', 9, 12, '&nbsp;هغه به قاتلانو نه بدل اخلى، د مظلومانو نه بې‌خبره نۀ دے او نۀ د دړدمندانو د فرياد نه بې‌خبره دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13046, 'Psalms 9:13', 'Psalms', 9, 13, '&nbsp;رحم په ما وکړه، اے مالِکه خُدايه، ګوره دشمنانو ډېر تنګ کړے يم، ما د مرګ د خولې نه را آزاد کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13047, 'Psalms 9:14', 'Psalms', 9, 14, '&nbsp;د صيون لور په دروازو به ستا صِفت او د خلاصون خوشحالى وکړم نو داسې به زۀ ستا د ثناء صِفت اعلان وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13048, 'Psalms 9:15', 'Psalms', 9, 15, '&nbsp;قومونه کومه کنده چې وباسى نو په خپله ورګزار به شى، په پټ خور کړى دام کښې خپله راګېر به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13049, 'Psalms 9:16', 'Psalms', 9, 16, '&nbsp;مالِک خُدائ پېژندلے شى، په خپل اِنصاف سره، خو اوس راګېر دى بدعمله خپل کردار سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13050, 'Psalms 9:17', 'Psalms', 9, 17, '&nbsp;ځى به لاندې قبر ته ټول بدکاران، چې هېر کړے يې مالِک خُدائ دے هغه ټول قومونه به وى ورروان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13051, 'Psalms 9:18', 'Psalms', 9, 18, '&nbsp;حاجت لرونکې به د تل دپاره هېرولے نۀ شى، دا مظلومان خلق به نااُميده پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13052, 'Psalms 9:19', 'Psalms', 9, 19, '&nbsp;پاڅه، اے مالِکه خُدايه، بنى آدم چې سرکشى ونۀ کړى، د قومونو دې عدالت ستا د وړاندې وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13053, 'Psalms 9:20', 'Psalms', 9, 20, '&nbsp;تۀ مالِکه خُدايه يره باندې هغوئ ويروه، قومونه تۀ په دې پوهه وه چې هغوئ فانى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13054, 'Psalms 10:1', 'Psalms', 10, 1, '&nbsp;اے مالِکه خُدايه، تۀ زما نه ولې لرې ودرېږې؟ په وخت د مصيبت کښې تۀ ما نه ولې خپل ځان پټوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13055, 'Psalms 10:2', 'Psalms', 10, 2, '&nbsp;په خپل غرور کښې بدکاران غريبانان خپل ځان ته پرزوى، دوئ په خپله په خپلو بدچلونو کښې راګېر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13056, 'Psalms 10:3', 'Psalms', 10, 3, '&nbsp;د خپل نفس لافې کوى دا بدکاران، په مالِک خُدائ لعنت کوى او د هغۀ نه اِنکار کوى لالچيان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13057, 'Psalms 10:4', 'Psalms', 10, 4, '&nbsp;خپل غرور کښې بدکاران طلب نۀ کوى د خُدائ پاک، په خپلو ټولو سوچونو کښې هيڅ پرواه نۀ کړى د خُدائ پاک.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13058, 'Psalms 10:5', 'Psalms', 10, 5, '&nbsp;تل کاميابه وى هغوئ په دشمنانو پورې خندا کوى، ستا قانون نۀ منى دا مغروران.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13059, 'Psalms 10:6', 'Psalms', 10, 6, '&nbsp;ځان سره دوئ وائى چې، ”هيڅ به مو نۀ کړى په لړزان، ټول عمر زۀ به يم خوشحاله او د سختو به يم په امان.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13060, 'Psalms 10:7', 'Psalms', 10, 7, '&nbsp;خولۀ يې دروغژنه، کنځل ماره، دوکه بازه ده، د هغۀ ژبه غوڅونکې، تباه کوونکې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13061, 'Psalms 10:8', 'Psalms', 10, 8, '&nbsp;پروت د کلو خوا کښې پټ په پټه اِنتظار کوى، وژنى بې‌ګناه ګورى د ورايه پرې ګزار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13062, 'Psalms 10:9', 'Psalms', 10, 9, '&nbsp;لکه زمرى پټ په پرده کښې اِنتظار کوى، نيسى غريبان پروت دے په پټه اِنتظار کوى، رايې کاږى او په جال کښې يې راګېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13063, 'Psalms 10:10', 'Psalms', 10, 10, '&nbsp;نو مظلومان په کښې چخڼى شى، او د ظالم د زور سره رالاندې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13064, 'Psalms 10:11', 'Psalms', 10, 11, '&nbsp;بد کار د خپل ځان سره دا وائى چې، ”د خُدائ پاک هېر شوى دى، چې هيڅ نۀ وينى، سترګې يې پټې کړې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13065, 'Psalms 10:12', 'Psalms', 10, 12, '&nbsp;اے مالِکه خُدايه، راپاڅه، او بدکارانو ته سزا ورکړه. پاکه خُدايه مظلومان مۀ هېروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13066, 'Psalms 10:13', 'Psalms', 10, 13, '&nbsp;خُدائ ولې سپکوى دغه بدکاران؟ خپل ځان سره وائى چې، ”نشته تپوسونه،“ وائى دغه بدکاران.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13067, 'Psalms 10:14', 'Psalms', 10, 14, '&nbsp;خو تا په خپله دا تکليفونه او خفګان وليدلو، او تۀ په خپله دا وينې او عدالت کوې. تا ته ځان سپارلے دے بې‌وسه مظلومانو، مل يې تۀ او حفاظت کوې د بې‌پلارانو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13068, 'Psalms 10:15', 'Psalms', 10, 15, '&nbsp;لاسونه مات کړه د بدکاره بدعمله انسان، هغوئ له داسې بدله ورکړه چې يو ظالم هم پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13069, 'Psalms 10:16', 'Psalms', 10, 16, '&nbsp;د مالِک خُدائ بادشاهى به تل تر تله وى، د هغۀ د دُنيا نه به غېرقومونه هلاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13070, 'Psalms 10:17', 'Psalms', 10, 17, '&nbsp;اے مالِکه خُدايه، تا په خپله سوال زارى د مظلومانو واورېدله، تۀ هغوئ ډاډه کوې او سوالونه يې اورې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13071, 'Psalms 10:18', 'Psalms', 10, 18, '&nbsp;تۀ د بې‌پلاره مظلومانو محافظ يې، نو فانى انسان به دوئ په دې دُنيا کښې يرولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13072, 'Psalms 11:1', 'Psalms', 11, 1, '&nbsp;زۀ د مالِک خُدائ په پناه کښې يم. تۀ ولې راته وائې، ”لکه د مارغۀ چې غر ته والوځم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13073, 'Psalms 11:2', 'Psalms', 11, 2, '&nbsp;ګوره بدعمله خپله لينده راکاږى او غشى ويشتو ته برابروى، او د پټ ځائ نه په نېکانو باندې يې ورَوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13074, 'Psalms 11:3', 'Psalms', 11, 3, '&nbsp;هرکله چې بنيادونه ورانولے شى، نو رښتونى خلق به څۀ وکړے شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13075, 'Psalms 11:4', 'Psalms', 11, 4, '&nbsp;مالِک خُدائ په خپل مقدس کور کښې دے، هم اوس مالِک خُدائ د خپل آسمانى تخت نه بادشاهى کوى. هر يو انسان هغه په خپله د نزدې نه ګورى، او په زمکه هر يو کس آزمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13076, 'Psalms 11:5', 'Psalms', 11, 5, '&nbsp;مالِک خُدائ صادقان او بدکاران دواړه معلوموى، هغه د هغوئ نه نفرت کوى څوک چې ظلمونه خوښوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13077, 'Psalms 11:6', 'Psalms', 11, 6, '&nbsp;هغه به په بدکارانو او شريرانو بَل سکارۀ او تاودۀ ګوګړ ورَوى، په سوزونکو هواګانو سره ورته سزا ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13078, 'Psalms 11:7', 'Psalms', 11, 7, '&nbsp;بې‌شکه صادق مالِک خُدائ د اِنصاف سره مينه کوى، او نېکان خلق به د هغۀ د مخ ديدن کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13079, 'Psalms 12:1', 'Psalms', 12, 1, '&nbsp;اے مالِکه خُدايه، تۀ زمونږ مددګار شه، په تېزۍ سره پناه کيږى ستا نېک بنيادمان، ستا وفاداران دى د دې زمکې نه روان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13080, 'Psalms 12:2', 'Psalms', 12, 2, '&nbsp;وائى دروغ په خپلو کښې يو بل ته ګاونډيان، په زړۀ کښې دوکه باز او په غوړو شونډو دى ګويان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13081, 'Psalms 12:3', 'Psalms', 12, 3, '&nbsp;مالِکه تۀ په خپله دوئ نه پرې کړه غوړ شونډان دوئ نه هغه ژبې پرې کړه چې په لافو دى ګويان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13082, 'Psalms 12:4', 'Psalms', 12, 4, '&nbsp;دوئ وائى چې، ”مونږ به په خپله ژبه هر څۀ حاصل کړُو، څوک مو د وينا نه ايسارولے شى چې مونږ خپلې شونډې استعمال کړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13083, 'Psalms 12:5', 'Psalms', 12, 5, '&nbsp;فرمائى مالِک خُدائ، ”زياتے مې وليدلو چې وشو په حاجتمندانو فرياد او زبيرګى ما واورېدل چې وکړل غريبانانو، نو زۀ به ورشم چې هغوئ بچ کړم، څنګه چې هغوئ زما د مدد لرى ارمان.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13084, 'Psalms 12:6', 'Psalms', 12, 6, '&nbsp;د مالِک خُدائ وعدې دى پاکې، لکه سپين زر چې صفا شى اووۀ ځله په بټۍ کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13085, 'Psalms 12:7', 'Psalms', 12, 7, '&nbsp;اے مالِکه خُدايه مونږ يُو په اطمينان چې به وساتې نسل د دروغژنو نه به کړې تل په حفاظت دا مظلومان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13086, 'Psalms 12:8', 'Psalms', 12, 8, '&nbsp;خو په هر ځائ کښې ګرځيږى بدکاران ټول بدۍ ته په ښۀ سترګه ګورى انسانان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13087, 'Psalms 13:1', 'Psalms', 13, 1, '&nbsp;اے مالِکه خُدايه، تر کومه به تۀ ما هېروې؟ تر ابده پورې تر کومه به تۀ بل خوا ته ګورې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13088, 'Psalms 13:2', 'Psalms', 13, 2, '&nbsp;تر کومه به زما ذهن پرېشانه وى هره ورځ زما په زړۀ کښې به تر کومه خفګان وى؟ تر کومه به دشمن په ما باندې غالب وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13089, 'Psalms 13:3', 'Psalms', 13, 3, '&nbsp;مالِکه زما خُدايه، راشه ما له جواب راکړه. سترګې مې روښانه کړه ګنې مړ به شم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13090, 'Psalms 13:4', 'Psalms', 13, 4, '&nbsp;مۀ خوشحالوه ما باندې تۀ زما دشمنان، چې، ”ور مو کړُو شکست،“ وائى به دوئ مدام. دوئ مۀ خوشحالوه زما په لړزان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13091, 'Psalms 13:5', 'Psalms', 13, 5, '&nbsp;ستا په بې‌حده مينه لرم ايمان، زۀ به خوشحالى کوم ځکه چې ستا د خلاصون منم احسان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13092, 'Psalms 13:6', 'Psalms', 13, 6, '&nbsp;مالِکه خُدايه، ستا د صِفت سرود به کړم بيان، ځکه چې تۀ يې په ما مهربان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13093, 'Psalms 14:1', 'Psalms', 14, 1, '&nbsp;”نشته دے خُدائ،“ په خپل زړۀ کښې وائى کم عقلان، دوئ دى فاسدان ښۀ عمل يې نشته يو هم داسې نشته چې وى نېکان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13094, 'Psalms 14:2', 'Psalms', 14, 2, '&nbsp;مالِک پاس د آسمان نه ګورى ټول بنيادمان هغه ګورى چې په رښتيا په دُنيا شته داسې پوهان، څوک شته په دې دُنيا د خُدائ متلاشيان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13095, 'Psalms 14:3', 'Psalms', 14, 3, '&nbsp;نشته يو هم نشته ټول دى اوړېدلى په غلطه لار روان، نشته دے يو کس هم چرته نشته دے نېکان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13096, 'Psalms 14:4', 'Psalms', 14, 4, '&nbsp;ولې دوئ نۀ زده کوى څوک چې دى بدکاران، دوئ خورى لکه روټۍ زما خلق انسانان مالِک ته به د دُعا فکر ونۀ کړى دا بدکاران؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13097, 'Psalms 14:5', 'Psalms', 14, 5, '&nbsp;په سخته يره کښې به پراتۀ وى بدکاران، ځکه پاک خُدائ مل دے د صادقانو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13098, 'Psalms 14:6', 'Psalms', 14, 6, '&nbsp;اے بدکارانو تاسو په غريبانانو ظلم کوئ، خو مالِک خُدائ دے د خپلو خلقو نګهبان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13099, 'Psalms 14:7', 'Psalms', 14, 7, '&nbsp;څوک به راشى د صيون چې آزاد کړى اِسرائيليان، کله چې مالِک خُدائ بيا آباد کړى خپل قوميان، يعقوب به خوشحالى وکړى او خوشحاله به شى اِسرائيليان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13100, 'Psalms 15:1', 'Psalms', 15, 1, '&nbsp;څوک مالِکه خُدايه ستا مقدس کور کښې عبادت ته داخلېدے شى؟ ستا په مقدس غر څوک ستا حضور کښې اوسېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');